macro_rules! deps {
    () => {
        Address!();
        Reader!();
        UnwindContext!();
        CallFrameInstruction!();
        StoreOnHeap!();
        CallFrameInstructionIter!();
        UnwindContextStorage!();
    };
}

macro_rules! UnwindTable {
    () => {
        deps!();
        # [doc = " The `UnwindTable` iteratively evaluates a `FrameDescriptionEntry`'s"] # [doc = " `CallFrameInstruction` program, yielding the each row one at a time."] # [doc = ""] # [doc = " > 6.4.1 Structure of Call Frame Information"] # [doc = " >"] # [doc = " > DWARF supports virtual unwinding by defining an architecture independent"] # [doc = " > basis for recording how procedures save and restore registers during their"] # [doc = " > lifetimes. This basis must be augmented on some machines with specific"] # [doc = " > information that is defined by an architecture specific ABI authoring"] # [doc = " > committee, a hardware vendor, or a compiler producer. The body defining a"] # [doc = " > specific augmentation is referred to below as the “augmenter.”"] # [doc = " >"] # [doc = " > Abstractly, this mechanism describes a very large table that has the"] # [doc = " > following structure:"] # [doc = " >"] # [doc = " > <table>"] # [doc = " >   <tr>"] # [doc = " >     <th>LOC</th><th>CFA</th><th>R0</th><th>R1</th><td>...</td><th>RN</th>"] # [doc = " >   </tr>"] # [doc = " >   <tr>"] # [doc = " >     <th>L0</th> <td></td>   <td></td>  <td></td>  <td></td>   <td></td>"] # [doc = " >   </tr>"] # [doc = " >   <tr>"] # [doc = " >     <th>L1</th> <td></td>   <td></td>  <td></td>  <td></td>   <td></td>"] # [doc = " >   </tr>"] # [doc = " >   <tr>"] # [doc = " >     <td>...</td><td></td>   <td></td>  <td></td>  <td></td>   <td></td>"] # [doc = " >   </tr>"] # [doc = " >   <tr>"] # [doc = " >     <th>LN</th> <td></td>   <td></td>  <td></td>  <td></td>   <td></td>"] # [doc = " >   </tr>"] # [doc = " > </table>"] # [doc = " >"] # [doc = " > The first column indicates an address for every location that contains code"] # [doc = " > in a program. (In shared objects, this is an object-relative offset.) The"] # [doc = " > remaining columns contain virtual unwinding rules that are associated with"] # [doc = " > the indicated location."] # [doc = " >"] # [doc = " > The CFA column defines the rule which computes the Canonical Frame Address"] # [doc = " > value; it may be either a register and a signed offset that are added"] # [doc = " > together, or a DWARF expression that is evaluated."] # [doc = " >"] # [doc = " > The remaining columns are labeled by register number. This includes some"] # [doc = " > registers that have special designation on some architectures such as the PC"] # [doc = " > and the stack pointer register. (The actual mapping of registers for a"] # [doc = " > particular architecture is defined by the augmenter.) The register columns"] # [doc = " > contain rules that describe whether a given register has been saved and the"] # [doc = " > rule to find the value for the register in the previous frame."] # [doc = " >"] # [doc = " > ..."] # [doc = " >"] # [doc = " > This table would be extremely large if actually constructed as"] # [doc = " > described. Most of the entries at any point in the table are identical to"] # [doc = " > the ones above them. The whole table can be represented quite compactly by"] # [doc = " > recording just the differences starting at the beginning address of each"] # [doc = " > subroutine in the program."] # [derive (Debug)] pub struct UnwindTable < 'a , 'ctx , R , S = StoreOnHeap > where R : Reader , S : UnwindContextStorage < R :: Offset > , { code_alignment_factor : Wrapping < u64 > , data_alignment_factor : Wrapping < i64 > , address_size : u8 , next_start_address : u64 , last_end_address : u64 , returned_last_row : bool , current_row_valid : bool , instructions : CallFrameInstructionIter < 'a , R > , ctx : & 'ctx mut UnwindContext < R :: Offset , S > , }
    };
}

UnwindTable!()